export type Region =
  | "Caribbean"
  | "North America"
  | "Eastern Pacific"
  | "Southeast Asia"
  | "Australia & Pacific"
  | "Red Sea & East Africa"
  | "Africa & Indian Ocean"
  | "Europe & Mediterranean"
  | "South America";

export type SiteType =
  | "Reef" | "Wall" | "Wreck" | "Cave" | "Pier" | "Pinnacle" | "Seamount" | "Sandbar" | "Muck" | "Kelp" | "Monument" | "Rock" | "Thila";

export type Difficulty = "Beginner" | "Intermediate" | "Advanced" | "Technical";

export interface DiveSite {
  id: string;
  name: string;
  lat: number;
  lng: number;
  region: Region;
  country: string;
  types: SiteType[];
  description: string;
  depthRange: string;
  difficulty: Difficulty;
  conditions: string;
  visibility: string;
  temp: string;
  bestSeason: string;
  rating: number;
  tz: string;
  us?: boolean;
  nwsZone?: string;
  nwsOffice?: string;
  ndbc?: string;
  tides?: string;
  metUrl?: string;
}

